(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.03-t*0.5)*8+Math.cos(sy*0.025+t*0.4)*6;
  const w2y = Math.cos(sy*0.03+t*0.45)*8+Math.sin(sx*0.028-t*0.55)*6;
  const px = sx+w2x, py = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.2],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.65+3)*70,40+Math.cos(t*0.75)*90,0.11,2.1,0.85],
    [400+Math.cos(t*0.45+2)*60,200+Math.sin(t*0.85+1)*70,0.055,2.4,1.05]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((px-sX)**2+(py-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    mS+=Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,mod=mS/n;
  const bg=(Math.sin(px*0.04+py*0.025+t*0.8)+Math.sin(px*0.03-py*0.04+t*1.1))/2+Math.sin((px+py)*0.12+t*2.5)*0.2+Math.sin((px-py)*0.1-t*2)*0.2;
  const dist=Math.sqrt((px-cx)**2+(py-cy)**2),ang=Math.atan2(py-cy,px-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2-t*2.0))*0.28;
  const fine=(Math.sin(px*0.2+t*3)*Math.sin(py*0.2-t*2.5)+Math.sin(px*0.15-py*0.15+t*1.8)*0.7)*0.15;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act*0.6+mod-inh*0.5+fine)*1.8);
  const cross=r1*r2*1.5;
  const cell=Math.tanh((Math.sin(px*0.15)*Math.sin(py*0.15)+Math.sin((px+py)*0.1+t)*0.5)*1.5)*0.3;
  const laplacian=Math.sin(px*0.08+py*0.06)*Math.cos(px*0.06-py*0.08+t*0.7)*0.2;
  const blend=r1*0.45+r2*0.2+cross*0.15+cell*0.12+laplacian*0.08;
  const v=blend*0.5+0.5;
  const pal=[[12,8,52],[25,30,95],[18,75,115],[15,130,135],[50,165,120],[140,185,80],[210,175,60],[225,130,55],[200,85,70],[165,50,75],[110,30,85],[55,18,68],[12,8,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.82+Math.sin(r1*Math.PI)*0.12+Math.abs(cross)*0.06;
  const edge=Math.abs(r1)>0.7?1.12:Math.abs(r2)>0.6?1.06:1.0;
  const glow=Math.max(0,cross)*0.15;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*80)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*40)|0
  ];
}
